INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (1, 0, 'chris', 'KDE 3.2 Released', '2004-02-03 09:20:00', 'The KDE Project has released KDE 3.2, the first major release since 3.1 a year ago. The big new pieces are <b>Kontact</b>, which pulls KMail, KOrganizer, KAddressBook and KNotes into one window, the <b>Kopete</b> instant messenger, the <b>JuK</b> music player and KWallet for storing passwords. Most people will notice the speed first: applications start noticeably faster than in 3.1.', 'Konqueror picked up better tab handling and an improved KHTML engine, with a long list of rendering fixes shared with Apple\'s Safari team. The new Plastik style ships alongside Keramik, and plenty of readers will be switching to it within the hour.<br><br>Source tarballs are on the KDE FTP mirrors now. Binary packages for SuSE, Mandrake, Fedora and Slackware are trickling in; Debian users will have to wait for unstable as usual.', 0, 2207, 3, 'chris', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (2, 0, 'chris', 'Firebird Is Dead, Long Live Firefox 0.8', '2004-02-09 22:05:00', 'The Mozilla Foundation has released version 0.8 of its standalone browser, and with it a new name: <b>Mozilla Firefox</b>. The Firebird name ran into trouble with the Firebird database project, and this time the Foundation says the name is final. Thunderbird 0.5 came out alongside it.', 'Apart from the name, 0.8 brings a new download manager, a proper Windows installer, an offline mode and a cleaned-up default theme. Your Firebird profile is not migrated automatically on Linux, so copy your ~/.phoenix directory over to ~/.mozilla/firefox if you want your bookmarks and extensions back.<br><br>Builds for Linux, Windows and Mac OS X are on the Mozilla FTP site.', 2, 3418, 5, 'chris', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (1, 0, 2, '2004-02-09 22:31:00', 'gnomeuser2k', '', '', '142.177.2.203', 'Third time lucky', 'Phoenix, Firebird, Firefox. I will believe it when the next release is out with the same name.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (2, 0, 2, '2004-02-10 07:58:00', '', '', '', '142.177.53.242', 'Download manager', 'The new download manager alone is worth it. Copied my profile over and everything just works.', 0, 0);
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (3, 0, 'chris', 'Windows 2000 and NT 4 Source Code Leaks', '2004-02-13 08:40:00', 'Microsoft has confirmed that portions of the Windows 2000 and Windows NT 4.0 source code have turned up on the internet. The company says the leak did not come from a breach of its own network, and the trail seems to lead to a partner with source access.', 'The archive was passed around on IRC and peer-to-peer networks within hours. Free software developers working on Wine, Samba and ReactOS have been quick to tell contributors to stay well away from it: anyone who has looked at the code should not submit patches. Expect the security crowd to have a field day either way.', 0, 2864, 10, 'deb_hacker', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (4, 0, 'chris', 'PHP 5.0 Beta 4 Out for Testing', '2004-02-15 14:10:00', 'The PHP Group has published PHP 5.0.0 Beta 4, which it expects to be the last beta before release candidates. The release is built on the Zend Engine 2 with its new object model, and bundles SimpleXML, SQLite and the new mysqli extension for MySQL 4.1. This site runs on PHP 4 and will be staying there for a while, thanks.', '', 0, 1306, 11, 'chris', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (5, 0, 'chris', 'Linux 2.6.3 Released', '2004-02-18 23:10:00', 'Linus has released Linux 2.6.3. This one is mostly fixes: networking and filesystem cleanups, updated drivers for a good number of network cards and SCSI controllers, and the usual round of architecture updates. Marcelo also put out 2.4.25 the same day for those staying on the stable series.', '', 1, 2489, 2, 'chris', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (3, 0, 5, '2004-02-19 09:14:00', 'kernel_tinkerer', '', '', '81.152.27.171', '2.4.25 too', '2.4.25 has the mremap fix as well. Update your servers.', 0, 0);
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (6, 0, 'chris', 'XFree86 4.4.0 Ships Under New License', '2004-03-01 11:30:00', 'XFree86 4.4.0 is out, and the release notes are getting less attention than the license. The project has moved to the XFree86 License 1.1, which adds a credit clause that the FSF says is incompatible with the GPL. Debian, Red Hat, Mandrake and Gentoo have all said they will not ship 4.4.0 under these terms.', 'Most distributions are sticking with 4.3.0 plus their own patches for now. The X.Org Foundation, formed in January, and the X server work going on at freedesktop.org are the obvious places for distributions to go next, and several vendors have hinted that is where they are looking.<br><br>For users nothing changes today: 4.3.0 keeps working, and your nvidia driver does not care either way.', 2, 2950, 8, 'kernel_tinkerer', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (4, 0, 6, '2004-03-01 12:05:00', 'slackbob', '', '', '142.177.135.154', 'Slackware?', 'Anyone know what Pat is going to do? Slackware usually ships whatever upstream releases.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (5, 0, 6, '2004-03-01 14:44:00', 'kernel_tinkerer', '', '', '66.71.232.114', 'Re: Slackware?', 'No word yet. My guess is that everyone ends up on the X.Org tree by the end of the year anyway.', 0, 0);
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (7, 0, 'chris', 'SCO Sues AutoZone and DaimlerChrysler', '2004-03-04 09:05:00', 'The SCO Group has filed two more lawsuits. AutoZone, which moved its stores from SCO OpenServer to Linux, is being sued in Nevada for copyright infringement. DaimlerChrysler is being sued in Michigan for failing to certify its compliance with its old Unix license agreement.', 'Neither suit is the long-promised case against a big Linux end user over the kernel itself, and Groklaw readers were quick to point out that the DaimlerChrysler complaint is a contract dispute. The IBM case grinds on in Utah, Novell is still disputing that SCO owns the Unix copyrights at all, and SCO\'s stock price continues to do interesting things. Discuss, but keep it civil, please.', 4, 3911, 9, 'chris', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (6, 0, 7, '2004-03-04 09:40:00', 'mwalsh', '', '', '66.71.35.133', 'Contract dispute', 'The DaimlerChrysler one reads like they did not send back a form. Not exactly the smoking gun.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (7, 0, 7, '2004-03-04 10:12:00', '', '', '', '24.18.230.101', 'AutoZone', 'AutoZone was a SCO customer, so SCO knows exactly what they run. That is presumably why they picked them.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (8, 0, 7, '2004-03-04 12:30:00', 'deb_hacker', '', '', '142.177.170.94', 'Re: AutoZone', 'Which says a lot about how confident they are about suing anyone else.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (9, 0, 7, '2004-03-05 08:55:00', 'penguinista', '', '', '213.37.44.158', 'Groklaw', 'Groklaw has both complaints up already, with annotations. Worth a read if you have the stomach for it.', 0, 0);
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (8, 0, 'chris', 'Fedora Core 1, Four Months On', '2004-03-05 14:20:00', 'I put Fedora Core 1 on my home and work machines in November and thought readers might want a report from the trenches. Short version: it is Red Hat 9 with newer packages, yum works well, and the community repositories fill in the MP3 and DVD gaps.', 'The kernel is still 2.4.22, which is the biggest thing I miss. Fedora Core 2 is supposed to move to 2.6 and add SELinux, and there are test releases out for the brave. GNOME 2.4 and KDE 3.1.4 are both fine, though KDE people will want to grab 3.2 from the kde-redhat project. If you are on Red Hat 9 and your support runs out in April, this is the painless upgrade.', 0, 1487, 6, 'penguinista', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (9, 0, 'chris', 'GNOME 2.6 Slated for Late March', '2004-03-08 16:45:00', 'The GNOME release team says GNOME 2.6 is on track for the end of March. The headline changes are the new GTK+ 2.4 file chooser, which finally replaces the old file selection dialog, and a <b>spatial</b> Nautilus, which opens every folder in its own window and remembers where you left it.', 'The spatial mode has started a predictable amount of argument on the mailing lists. You can switch Nautilus back to browser mode with a gconf key, and the Epiphany web browser becomes the default browser in this release.', 0, 1702, 4, 'gnomeuser2k', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (10, 0, 'chris', 'KDE 3.2.1 Fixes Konqueror and Kontact Bugs', '2004-03-09 21:30:00', 'KDE 3.2.1 is out, the first maintenance release in the 3.2 series. It is a bug fix and translation update, with fixes in Konqueror, KMail and Kontact among others. Upgrading from 3.2 is recommended.', '', 1, 1155, 3, 'mwalsh', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (10, 0, 10, '2004-03-10 07:20:00', 'mwalsh', '', '', '81.152.16.77', 'Kontact', 'The Kontact crash when switching to the calendar is fixed. Thanks, KDE folks.', 0, 0);
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (11, 0, 'chris', 'Sarge Freeze Talk Heats Up Again', '2004-03-10 13:10:00', 'There is fresh discussion on debian-devel about when Sarge might freeze. The new debian-installer and the transition to newer toolchains are the main things still in the way, and nobody wants to put a date on it.', 'Woody is now more than eighteen months old, and its 2.2 and 2.4 kernels and XFree86 4.1 are starting to show. In the meantime the testing distribution is in pretty good shape, and plenty of readers already run Sarge on the desktop. The installer team is asking for test reports on as much odd hardware as people can find.', 0, 1094, 7, 'deb_hacker', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (12, 0, 'chris', 'Linux 2.6.4 Released', '2004-03-11 10:40:00', 'Linux 2.6.4 is out. Like 2.6.3 it is a consolidation release, but a large one: the changelog runs to several hundred entries, with updated ALSA sound drivers, NFS and XFS fixes, USB and input work, and a long list of network driver updates.', 'If you have been holding off on 2.6 because of a driver regression, it is worth checking the changelog. A few readers in the forums have reported that USB 2.0 external drives behave much better than they did in 2.6.2. The binary nvidia and ATI drivers need their usual patches.<br><br>The 2.6 series has now had four point releases in three months, and most of the big distributions are planning to switch over in their spring releases. Fedora Core 2 and SuSE 9.1 are both expected to ship with 2.6.', 5, 2732, 2, 'kernel_tinkerer', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (11, 0, 12, '2004-03-11 11:02:00', 'kernel_tinkerer', '', '', '203.12.117.147', 'USB 2.0 finally behaves', 'Built it on my Athlon box this morning. My external USB 2.0 drive does about 20 MB/s now, it was crawling along at USB 1.1 speeds on 2.6.2. Nice to see.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (12, 0, 12, '2004-03-11 11:47:00', 'deb_hacker', '', '', '24.18.89.97', 'Re: USB 2.0 finally behaves', 'Any word on when Debian unstable gets a kernel-image package for this? I would rather not build my own on the work machine again.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (13, 0, 12, '2004-03-11 13:15:00', '', '', '', '24.18.224.20', 'nvidia', 'The nvidia 5336 driver still needs the minion.de patches with 2.6.4. Works fine once you apply them.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (14, 0, 12, '2004-03-11 16:20:00', 'gnomeuser2k', '', '', '66.71.32.153', 'Still on 2.4 here', 'Not that it matters much on my old box with a plain UHCI controller. I will wait for my distribution to ship it.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (15, 0, 12, '2004-03-12 08:05:00', 'slackbob', '', '', '66.71.129.16', 'Re: Still on 2.4 here', 'Same. 2.4.25 runs my P200 router fine and I see no reason to touch it. The desktop is a different story, 2.6 feels a lot snappier under load.', 0, 0);
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (13, 0, 'chris', 'New Survey: Which Desktop Do You Use?', '2004-03-13 12:00:00', 'With KDE 3.2 out and GNOME 2.6 on the way, it seemed like a good time to ask. The new survey is in the right column. Results from the old 2.6 kernel survey are in the <a href="modules.php?name=Surveys">survey archive</a>; about half of you are still waiting for your distribution to ship it.', '', 2, 812, 1, 'chris', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (16, 0, 13, '2004-03-13 12:40:00', 'slackbob', '', '', '81.152.212.157', 'Missing option', 'Where is twm? Some of us like it simple.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (17, 0, 13, '2004-03-13 15:02:00', 'mwalsh', '', '', '203.12.88.159', 'Re: Missing option', 'That is what Other is for, Bob.', 0, 0);
INSERT INTO nuke_stories (sid, catid, aid, title, time, hometext, bodytext, comments, counter, topic, informant, notes, ihome, alanguage, acomm, haspoll, pollID, score, ratings, associated) VALUES (14, 0, 'chris', 'Open Source Planet Turns Two', '2004-03-14 09:15:00', 'Open Source Planet went online two years ago this week, on a borrowed Pentium II under a desk in Columbus. Thanks to everyone who submitted stories, argued in the comments and sent in corrections.', 'Some numbers: over 180,000 page views, close to 600 stories, and a surprising number of you who still read us in Lynx. Last month we moved the site to PHP-Nuke 7.1 and switched the forums to the built-in phpBB version, which fixed most of the login problems people were mailing about. The server is now a donated Athlon in a real rack. More of the same for year three.', 2, 407, 1, 'chris', '', 0, '', 0, 0, 0, 0, 0, '');
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (18, 0, 14, '2004-03-14 09:51:00', 'deb_hacker', '', '', '142.177.16.192', 'Happy birthday', 'Two years already. Here is to a third, and to the forums staying up this time.', 0, 0);
INSERT INTO nuke_comments (tid, pid, sid, date, name, email, url, host_name, subject, comment, score, reason) VALUES (19, 0, 14, '2004-03-14 10:22:00', 'gnomeuser2k', '', '', '142.177.77.183', 'Congrats', 'Read it every morning. Keep it up.', 0, 0);
