INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (16, 5, 2, 3, 1078419720, '1812357b', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (16, 'a1b2c3d4e5', '', 'Or they just needed a Linux user who could not argue they never had a SCO license.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (17, 5, 2, 5, 1078433280, '18128cf3', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (17, 'a1b2c3d4e5', '', 'Either way it is not the big end-user case they kept promising.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (18, 5, 2, 2, 1078496400, '1812cc92', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (18, 'a1b2c3d4e5', '', 'Story comments are going the same way, so I will leave this open. Keep it civil.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (19, 6, 5, 9, 1078597800, '181267c4', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (19, 'a1b2c3d4e5', 'Fedora Core 1 or wait for FC2?', 'New to Linux. Red Hat 9 on my desktop now. Upgrade to FC1 or wait for FC2?');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (20, 6, 5, 7, 1078600500, '1812c594', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (20, 'a1b2c3d4e5', '', 'FC1 now. Upgrading from Red Hat 9 is easy and FC2 is still a couple of months away.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (21, 6, 5, 9, 1078624260, '1812d09f', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (21, 'a1b2c3d4e5', '', 'Thanks, downloading the ISOs now.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (22, 7, 6, 4, 1078714800, '1812ed9b', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (22, 'a1b2c3d4e5', 'ICQ vs. Jabber for *nix users', 'Is anyone still on ICQ? Half my friends have moved to Jabber and the other half are on MSN.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (23, 7, 6, 8, 1078752660, '1812dc6a', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (23, 'a1b2c3d4e5', '', 'Gaim does all of them at once, so I stopped caring.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (24, 7, 6, 3, 1078754700, '18120634', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (24, 'a1b2c3d4e5', '', 'Jabber. At least I can run my own server.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (25, 8, 4, 4, 1078798620, '1812a7cf', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (25, 'a1b2c3d4e5', 'USB 2.0 external drive slow under 2.6.3', 'My external drive copies at about 1 MB/s. Is ehci_hcd supposed to load automatically?');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (26, 8, 4, 5, 1079278080, '1812bdca', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (26, 'a1b2c3d4e5', '', 'Check lsmod. If ehci_hcd is missing, the drive falls back to USB 1.1 speeds. 2.6.4 fixed it for me.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (27, 9, 3, 9, 1078875840, '18122730', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (27, 'a1b2c3d4e5', 'Firefox 0.8 lost my bookmarks', 'Installed Firefox 0.8 over Firebird and my bookmarks are gone. Help?');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (28, 9, 3, 4, 1078877400, '1812da12', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (28, 'a1b2c3d4e5', '', 'They are not gone, Firefox uses a new profile directory. Copy bookmarks.html from ~/.phoenix to ~/.mozilla/firefox.');
INSERT INTO nuke_bbposts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count) VALUES (29, 9, 3, 9, 1078878360, '18122721', '', 1, 0, 1, 1, NULL, 0);
INSERT INTO nuke_bbposts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (29, 'a1b2c3d4e5', '', 'Found them. Thanks!');
